insert into public.hikam_sayings (id,text,kind,topic,note,source,created) values
('m1','لا تعدن عدة لا تثق من نفسك بإنجازها.','hikma','الأخلاق والآداب','','شذرات المطوع، ص3',1759500000000),
('m2','لا يغرنك المرتقى السهل إذا كان المنحدر وعرا.','hikma','العقل والحكمة','','شذرات المطوع، ص3',1759499940000),
('m3','عواقب الأعمال من جنسها، فالعمل الصالح عاقبة صالحة، والعمل الخبيث عاقبته خبيثة.','hikma','الأخلاق والآداب','','شذرات المطوع، ص3',1759499880000),
('m4','اللهم إنا نعوذ بك من بلاء ليس معه ثواب، ونسألك عافية معها ثواب.','hikma','الإيمان والعبادة','دعاء','شذرات المطوع، ص3',1759499820000),
('m5','اللهم إنا نعوذ بك من فقر ليس معه صبر، ونسألك غنى معه شكر.','hikma','الإيمان والعبادة','دعاء','شذرات المطوع، ص3',1759499760000),
('m6','الخضاب شاهد زور.','mathal','الحياة والزمن','','شذرات المطوع، ص3',1759499700000),
('m7','إذا كان الكثير كرما، كان الأكثر منه إسرافا، والأقل منه بخلا.','hikma','المال والاقتصاد','','شذرات المطوع، ص3',1759499640000),
('m8','من كانت حوائج الناس إليه، فهي نعمة من الله عليه.','hikma','العلاقات والناس','','شذرات المطوع، ص3',1759499580000),
('m9','أفضل المال ما أكسب أجرا، وقهر فقرا.','hikma','المال والاقتصاد','','شذرات المطوع، ص3',1759499520000),
('m10','أكرم الناس من أعطى من لا يرجوه، وأنال قبل السؤال.','hikma','الأخلاق والآداب','','شذرات المطوع، ص3',1759499460000),
('m11','قال محتضر : الرجوع إلى من يرجى عفوه، ويطمع في خيره، خير من البقاء مع من لا يؤمن شره، ولا يرجى عفوه.','hikma','الإيمان والعبادة','«محتضر» ترجيح من «حمتض» في المصدر','شذرات المطوع، ص3',1759499400000),
('m12','من شاب شعره فقد مات بعضه.','hikma','الحياة والزمن','','شذرات المطوع، ص3',1759499340000),
('m13','من أكثر من استماع الحكمة أوشك أن ينطق بها.','hikma','العلم والثقافة','','شذرات المطوع، ص3',1759499280000),
('m14','أربعة لا يستحي من خدمتهم : السلطان والوالد والضيف والدابة.','hikma','الأخلاق والآداب','','شذرات المطوع، ص3',1759499220000),
('m15','إذا جعلك الأمير من خواصه فلا تكثر الملق والدعاء، وعظمه ووقره عند الناس.','hikma','السياسة والقيادة','','شذرات المطوع، ص3',1759499160000),
('m16','رب كلمة تقول لقائلها : دعني.','mathal','الكلام والصمت','','شذرات المطوع، ص3',1759499100000),
('m17','العصبية : أن يرى الرجل شرار قومه خيرا من خيار قوم آخرين. وأن يرى باطل قومه أحق من حق قوم آخرين.','hikma','العلاقات والناس','','شذرات المطوع، ص3',1759499040000),
('m18','من محاسن النوم أن فيه إعراض عن الأعراض.','hikma','الصحة والنفس','','شذرات المطوع، ص3',1759498980000),
('m19','لعل الفرج قريب وأنت لا تدري.','hikma','الصبر والشدائد','','شذرات المطوع، ص4',1759498920000),
('m20','من أساء إليك فقد مكنك من لذة الذم والغيبة، ومن أحسن إليك فقد حرمك لذة الذم ومزمزة الغيبة.','hikma','العلاقات والناس','','شذرات المطوع، ص4',1759498860000),
('m21','إذا زرت البخيل أعانك على الذم، وإذا زرت الكريم حرمك لذة الذم.','hikma','العلاقات والناس','','شذرات المطوع، ص4',1759498800000),
('m22','ناموس المشايخ قلة المزح وكثرة الصمت، وناموس الشباب كثرة المزح وقلة الصمت.','hikma','الكلام والصمت','','شذرات المطوع، ص4',1759498740000),
('m23','نسبة الصواب إلى قائله أحمد من التفرد بالادعاء.','hikma','العلم والثقافة','','شذرات المطوع، ص4',1759498680000),
('m24','من لم يسخط نفسه في شهوته، لم يرض ربه في طاعته.','hikma','الإيمان والعبادة','','شذرات المطوع، ص4',1759498620000),
('m25','لو اطلع ابن آدم على ما بقي من أجله، لزهد في طول ما يرجو من أمله.','hikma','الحياة والزمن','','شذرات المطوع، ص4',1759498560000),
('m26','هب المسيء قد عفي عنه، أليس قد فاته ثواب المحسنين.','hikma','الأخلاق والآداب','','شذرات المطوع، ص4',1759498500000),
('m27','رفاهة العيش ومحبة النساء والأولاد توهي العزم، وتكسر حمية الشجاعة، وتحبب السلامة، وتباعد من ركوب المخاطر.','hikma','العقل والحكمة','','شذرات المطوع، ص4',1759498440000),
('m28','ليس مع الاستئثار محبة، ولا مع المواساة بغضة.','hikma','العلاقات والناس','','شذرات المطوع، ص4',1759498380000),
('m29','الملك الذي يطلب طاعة رعيته بالإحسان والمودة، أحمد عاقبة وأفضل عافية من الذي يطلبها بالقهر والاستطالة.','hikma','السياسة والقيادة','','شذرات المطوع، ص4',1759498320000),
('m30','إذا غضبت على من تعاطى ما يغضبك، فاجعل بين غضبك ورضاك مدة بقدر ما تردعه عن تعاطي ما يغضبك.','hikma','الأخلاق والآداب','','شذرات المطوع، ص4',1759498260000),
('m31','لو أن أحدا قليل العلم عمل بعلمه لكان جديرا بالنجاة.','hikma','العلم والثقافة','','شذرات المطوع، ص4',1759498200000),
('m32','لو أن أحدا كثير العلم لم يعمل بعلمه لكان جديرا بالهلاك.','hikma','العلم والثقافة','','شذرات المطوع، ص4',1759498140000),
('m33','تعودوا الخير فإنما الخير عادة.','hikma','الأخلاق والآداب','','شذرات المطوع، ص4',1759498080000),
('m34','السحاب فحل الأرض.','mathal','الحياة والزمن','','شذرات المطوع، ص5',1759498020000),
('m35','إذا كان لك أكثري فتجاف عن أقلي.','mathal','العلاقات والناس','','شذرات المطوع، ص5',1759497960000),
('m36','الدرهم يزرع، والسيف يحصد.','hikma','السياسة والقيادة','','شذرات المطوع، ص5',1759497900000),
('m37','إن لم ترهب فأرغب.','mathal','السياسة والقيادة','','شذرات المطوع، ص5',1759497840000),
('m38','اشبع من تخشاه فإن لم تشبعه أكلك.','hikma','السياسة والقيادة','','شذرات المطوع، ص5',1759497780000),
('m39','استدم النعم بالشكر، والمقدرة بالعفو، والطاعة بالتألف، والنصر بالتواضع، والرحمة بالرحمة.','hikma','الأخلاق والآداب','','شذرات المطوع، ص5',1759497720000),
('m40','اطلب الرحمة بالرحمة، والستر بالستر، وتفريج الكرب بتفريج الكرب، والتجاوز بالتجاوز، والسماح بالسماح، والرفق بالرفق.','hikma','الأخلاق والآداب','','شذرات المطوع، ص5',1759497660000),
('m41','اطلب كل شيء من الله تعالى بأن تعمل مثله مع عباده.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497600000),
('m42','إذا أردت أن يكون الله سبحانه معك كما تريد، فعامل عباده كما يريد.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497540000),
('m43','ما تريده من الله تعالى اطلبه بأن تفعله مع عباده.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497480000),
('m44','إذا وضحت الحجة ثقل استماع المنازعة فيها.','hikma','الكلام والصمت','','شذرات المطوع، ص5',1759497420000),
('m45','أول طريق الحكمة اتهام الرأي، واحتقار النفس، ومعوقاتها الإعجاب بالرأي وتعظيم النفس.','hikma','العقل والحكمة','','شذرات المطوع، ص5',1759497360000),
('m46','أقدار الله تعالى تأتي على كل حال : فقير يستغني، وغني يفتقر، وشيخ يعمر، وطفل يموت، وطبيب يهلك، ومريض يعيش، فلا تأمن في أي حال.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497300000),
('m47','الطاعات تخفف من كربة الموت، والمعاصي تزيدها.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497240000),
('m48','من اشتغل بالطاعات أحب لقاء الله فخف عليه مجيء الأجل.','hikma','الإيمان والعبادة','','شذرات المطوع، ص5',1759497180000),
('m49','من اشتغل بمعاصي الله كره لقاء الله، فثقل عليه مجيء الأجل.','hikma','الإيمان والعبادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759497120000),
('m50','المبادرة في إثابة المحسن تعدل التثبت في عقوبة المسيء.','hikma','السياسة والقيادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759497060000),
('m51','إذا عم الشر فخير الناس النومة ( الخامل ).','hikma','العلاقات والناس','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759497000000),
('m52','استرجع شارد النعمة بالتوبة والاستغفار، واستدم راهنها بالشكر وكرم الجوار.','hikma','الإيمان والعبادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496940000),
('m53','الشكر يزرع، والكفر يحصد.','hikma','الإيمان والعبادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496880000),
('m54','من أطعمه التراب أكله التراب.','hikma','المال والاقتصاد','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496820000),
('m55','من كثر جده ثقل، ومن كثر هزله رذل، وليكن مقدار المزاح في الكلام، مقدار الملح في الطعام.','hikma','الكلام والصمت','في المصدر «هزل» بلا هاء؛ الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496760000),
('m56','آفة الأمن التفريط، وثمرة الخوف الحزم.','hikma','العقل والحكمة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496700000),
('m57','حاجة الحكيم إلى السفه حاجة العجين إلى الملح.','hikma','العقل والحكمة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496640000),
('m58','حاجة الحليم إلى الغضب حاجة الدواء إلى السم.','hikma','الأخلاق والآداب','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496580000),
('m59','الذي يقرأ القرآن إنما يحدث عن ربه.','hikma','الإيمان والعبادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496520000),
('m60','على ألافها الطير تقع.','mathal','العلاقات والناس','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496460000),
('m61','الذكر صابون القلوب، والاستغفار صابون الذنوب.','hikma','الإيمان والعبادة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496400000),
('m62','السفر يعطل العادات، ويكسب المستجدات.','hikma','الحياة والزمن','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496340000),
('m63','من بادر بالإنكار مخطئا وهو لا يعلم، أعذر ممن بادر بالإقرار مصيبا وهو لا يعلم.','hikma','العقل والحكمة','الصفحة 6 أو 7 (رقما الصفحتين متجاوران في المصدر)','شذرات المطوع',1759496280000),
